import base64, os
files = {
    "brain/host_body.py": "",
    "brain/nexus.py": "",
    "caps/native_vision/run.py": "",
    "caps/native_vision/capability.json": "",
    "caps/stock_browser_trader/run.py": "",
    "caps/stock_browser_trader/capability.json": "",
    "caps/stock_browser_trader/knowledge.json": "",
    "caps/n8n_attack_chain/run.py": "",
}
for path, data in files.items():
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'wb') as f:
        f.write(base64.b64decode(data))
    print(f'OK: {path}')
print('DEPLOY COMPLETE')
